<script lang="ts">import PageShell from '$lib/components/PageShell.svelte';import {page} from '$app/state';import {listings,orders,invoices} from '$lib/api';import type {Listing} from '$lib/types';let item=$state<Listing|null>(null),qty=$state(1),error=$state(''),invoice=$state<any>(null),paymentStatus=$state('');$effect(()=>{listings.one(page.params.id || "").then(v=>item=v).catch(e=>error=e.message)});async function order(){if(!item)return;error='';try{const order=await orders.create(item.id,qty);invoice=await invoices.create(order.id,order.amountSats);paymentStatus='Invoice created';const timer=setInterval(async()=>{try{const next=await invoices.status(invoice.id);invoice=next;if(next.status==='paid'){paymentStatus='Paid';clearInterval(timer)}}catch{clearInterval(timer)}},5000)}catch(e){error=e instanceof Error?e.message:'Unable to create invoice.'}}</script><PageShell eyebrow="LISTING DETAIL" title={item?.title||'Loading listing…'}>{#if error}<p class="alert">{error}</p>{:else if item}<div class="detail-grid"><div class="detail-art">♻</div><div class="form-card"><p class="muted">{item.producerName} · {item.location}</p><p>{item.description||'Fresh organic material, ready for collection.'}</p><label>Quantity ({item.unit})<input type="number" min="1" bind:value={qty}/></label><h2>{(qty*item.priceSats).toLocaleString()} sats</h2><button class="btn primary" onclick={order} disabled={!!invoice}>Create Lightning invoice ↗</button>{#if invoice}<div class="invoice-box"><p class="eyebrow">LIGHTNING INVOICE</p><img src={`https://quickchart.io/qr?text=${encodeURIComponent(invoice.bolt11)}&size=180`} alt="Lightning invoice QR code"/><code>{invoice.bolt11}</code><strong>{invoice.amountSats.toLocaleString()} sats</strong><p class="success">{paymentStatus}</p></div>{/if}</div></div>{/if}</PageShell>
